                for (int c = 0; c < 4; c++) {
                    if (dp[b][r][c] == 0.0) continue;
                    if (r == jr && c == jc) continue; // shouldn't be here

                    // Count valid moves
                    int count = 0;
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (nr < 0 || nr >= 4 || nc < 0 || nc >= 4) continue;
                        if (nr == jr && nc == jc) continue;
                        count++;
                    }

                    if (count == 0) {
                        // Robot stays? or stops? 
                        // If no valid moves, robot stays put until battery dies
                        dp[b-1][r][c] += dp[b][r][c];
                        continue;
                    }

                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (nr < 0 || nr >= 4 || nc < 0 || nc >= 4) continue;
                        if (nr == jr && nc == jc) continue;
                        dp[b-1][nr][nc] += dp[b][r][c] / count;
                    }
                }
            }
        }

