int main(void) {
    /*
      The statement provided is incomplete in this prompt, but this is the
      classic 1D random-walk probability problem:

      - Rooms are arranged linearly and indexed 0..n
      - Start at s
      - Battery room at t
      - Junk room at j
      - Each move consumes 1 battery point
      - At each step, the robot moves left/right with equal probability
      - At the ends, it has only one possible move inward
      - The robot stops immediately if it reaches the battery room or junk room
      - If battery becomes 0 before reaching either, it also stops
      - We must compute the probability that it stops at the battery room

      Input is multiple datasets:
        n s t j
      terminated by a line with n == 0

      Since the exact original statement is truncated, this implementation
      follows the standard interpretation above.

      DP:
        dp[k][i] = probability of eventually stopping at battery room
                   starting from room i with k battery points remaining.

      Transitions:
        if i == t: 1
        else if i == j: 0
        else if k == 0: 0
        else:
          interior: (dp[k-1][i-1] + dp[k-1][i+1]) / 2
          left end: dp[k-1][1]
          right end: dp[k-1][n-1]

      Memory optimized to 2 rows.
    */

    int n, s, t, j;

    while (scanf("%d", &n) == 1 && n != 0) {
        if (scanf("%d %d %d", &s, &t, &j) != 3) return 0;

        double prev[1005], cur[1005];

        for (int i = 0; i <= n; i++) {
            if (i == t) prev[i] = 1.0;
            else prev[i] = 0.0;
        }

        for (int k = 1; k <= n; k++) {
            for (int i = 0; i <= n; i++) {
                if (i == t) cur[i] = 1.0;
                else if (i == j) cur[i] = 0.0;
                else if (i == 0) cur[i] = prev[1];
                else if (i == n) cur[i] = prev[n - 1];
                else cur[i] = 0.5 * (prev[i - 1] + prev[i + 1]);
            }
            for (int i = 0; i <= n; i++) prev[i] = cur[i];
        }

        printf("%.6f\n", prev[s]);
    }

    return 0;
}

