        vector<vector<double>> dp(n, vector<double>(battery + 1, 0.0));

        // Base cases
        for (int b = 0; b <= battery; b++) {
            dp[battery_room][b] = 1.0; // already at battery room
            dp[junk_room][b] = 0.0;   // stuck in junk room
        }

        // Fill DP for decreasing battery
        for (int b = 1; b <= battery; b++) {
            for (int u = 0; u < n; u++) {
                if (u == battery_room || u == junk_room) continue;
                if (adj[u].empty()) {
                    dp[u][b] = 0.0; // can't move
                    continue;
                }
                double prob = 0.0;
                int deg = adj[u].size();
                for (int v : adj[u]) {
                    prob += dp[v][b - 1];
                }
                dp[u][b] = prob / deg;
            }
        }

        cout << fixed << setprecision(10) << dp[start][battery] << "\n";
    }

    return 0;
