/*
The statement provided is truncated, but this is the classic "robot in rooms"
probability DP:

- Rooms are numbered 1..n on a line.
- Robot starts at room s.
- Battery room is room b.
- Junk room is room j.
- Battery points = m.
- Each move consumes 1 battery point.
- From an interior room, robot moves left/right with probability 1/2 each.
- At an endpoint, it has only one possible move.
- Robot stops immediately if it reaches the battery room or the junk room.
- If battery becomes 0 before reaching battery room, it cannot move anymore.
- We must compute the probability that the robot stops at the battery room.

Input format assumed:
Multiple datasets:
m n s b j
terminated by m = 0

This matches the common form of the problem. We solve by DP:
dp[t][x] = probability of eventually reaching battery room starting from room x
with t battery points remaining.

Base:
dp[t][b] = 1
dp[t][j] = 0
dp[0][x] = 0 for other x

Transition:
If x is endpoint:
  dp[t][1] = dp[t-1][2]           (unless 1 is b/j handled by base)
  dp[t][n] = dp[t-1][n-1]
Else:
  dp[t][x] = (dp[t-1][x-1] + dp[t-1][x+1]) / 2

Output with 6 digits after decimal point.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m, n, s, b, j;
    while (cin >> m) {
        if (m == 0) break;
        cin >> n >> s >> b >> j;

        vector<double> prev(n + 1, 0.0), cur(n + 1, 0.0);

        for (int t = 0; t <= m; ++t) {
            fill(cur.begin(), cur.end(), 0.0);

            for (int x = 1; x <= n; ++x) {
                if (x == b) {
                    cur[x] = 1.0;
                } else if (x == j) {
                    cur[x] = 0.0;
                } else if (t == 0) {
                    cur[x] = 0.0;
                } else {
                    if (n == 1) {
                        cur[x] = 0.0;
                    } else if (x == 1) {
                        cur[x] = prev[2];
                    } else if (x == n) {
                        cur[x] = prev[n - 1];
                    } else {
                        cur[x] = 0.5 * (prev[x - 1] + prev[x + 1]);
                    }
                }
            }

            prev.swap(cur);
        }

        cout << fixed << setprecision(6) << prev[s] << '\n';
    }

    return 0;
}

