/*
 * The original statement provided here is truncated, but from the described behavior
 * we can model the standard "random walk on rooms with battery" process:
 *
 * - Rooms are numbered 1..N on a line.
 * - The robot starts at room S with B battery points.
 * - The battery room is at room T.
 * - The junk room is at room J.
 * - Each move consumes 1 battery point.
 * - At each step, the robot moves uniformly to an adjacent room:
 *      * from room 1 it must move to room 2
 *      * from room N it must move to room N-1
 *      * otherwise it moves left/right with probability 1/2 each
 * - If it reaches the battery room, it stops successfully.
 * - If it reaches the junk room, it cannot enter / stops unsuccessfully.
 * - If battery becomes 0 before reaching the battery room, it stops unsuccessfully.
 *
 * Input is assumed to contain multiple datasets:
 *   N B S T J
 * terminated by a line whose first value B is 0 in the original statement,
 * but since the full statement is missing, we robustly handle either:
 *   - single integer 0
 *   - line/dataset with B == 0
 *
 * Output:
 *   probability of stopping at the battery room for each dataset.
 *
 * Since the exact required formatting is not visible, we print with 6 digits after decimal,
 * which is the most common requirement for this type of problem.
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Integer nextIntOrNull() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            Integer a = fs.nextIntOrNull();
            if (a == null) break;

            // Try to support both possible input styles:
            // 1) dataset: N B S T J
            // 2) dataset starts with B only (not enough info here, but statement is truncated)
            // We proceed with the 5-integer interpretation, which is the only solvable one.
            int N = a;
            Integer bObj = fs.nextIntOrNull();
            if (bObj == null) break;
            int B = bObj;

            if (B == 0) break;

            Integer sObj = fs.nextIntOrNull();
            Integer tObj = fs.nextIntOrNull();
            Integer jObj = fs.nextIntOrNull();
            if (sObj == null || tObj == null || jObj == null) break;

            int S = sObj, T = tObj, J = jObj;

            double ans = solve(N, B, S, T, J);
            out.append(String.format(Locale.US, "%.6f%n", ans));
        }

        System.out.print(out.toString());
    }

    static double solve(int N, int B, int S, int T, int J) {
        // dp[stepsRemaining][position] is not needed fully; use rolling arrays.
        double[] cur = new double[N + 1];
        double[] next = new double[N + 1];

        // Base at time 0: success only if already at battery room.
        for (int pos = 1; pos <= N; pos++) {
            if (pos == T) cur[pos] = 1.0;
            else cur[pos] = 0.0;
        }

        // Build up for remaining battery from 1..B
        for (int b = 1; b <= B; b++) {
            for (int pos = 1; pos <= N; pos++) {
                if (pos == T) {
                    next[pos] = 1.0; // already stopped successfully
                } else if (pos == J) {
                    next[pos] = 0.0; // junk room is failure
                } else {
                    if (pos == 1) {
                        next[pos] = cur[2];
                    } else if (pos == N) {
                        next[pos] = cur[N - 1];
                    } else {
                        next[pos] = 0.5 * (cur[pos - 1] + cur[pos + 1]);
                    }
                }
            }
            double[] tmp = cur;
            cur = next;
            next = tmp;
        }

        return cur[S];
    }
}

import sys

def solve():
    data = sys.stdin.read().strip().split()
    idx = 0
    results = []

    while idx < len(data):
        b = int(data[idx])
        idx += 1
        if b == 0:
            break

        w = int(data[idx]); idx += 1
        h = int(data[idx]); idx += 1

        start = None
        battery_room = None
        junk_room = None

        grid = []
        for i in range(h):
            row = list(data[idx]); idx += 1
            grid.append(row)
            for j, ch in enumerate(row):
                if ch == 's':
                    start = (i, j)
                elif ch == 'b':
                    battery_room = (i, j)
                elif ch == 'j':
                    junk_room = (i, j)

        # Directions: up, down, left, right
        dirs = [(-1,0),(1,0),(0,-1),(0,1)]

        # dp[pos][battery] = probability
        dp = {}
        dp[(start[0], start[1], b)] = 1.0

        # We iterate until no change or until battery runs out
        changed = True
        while changed:
            changed = False
            new_dp = {}
            for (x, y, bat), prob in dp.items():
                if bat <= 0:
                    # No moves possible, stays here
                    new_dp[(x, y, 0)] = new_dp.get((x, y, 0), 0) + prob
                    continue
                if (x, y) == battery_room:
                    new_dp[(x, y, bat)] = new_dp.get((x, y, bat), 0) + prob
                    continue
                # Count possible moves
                moves = []
                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] != 'j':
                        moves.append((nx, ny))
                if not moves:
                    new_dp[(x, y, bat)] = new_dp.get((x, y, bat), 0) + prob
                    continue
                p_move = prob / len(moves)
                for nx, ny in moves:
                    key = (nx, ny, bat - 1)
                    new_dp[key] = new_dp.get(key, 0) + p_move
            if new_dp != dp:
                changed = True
                dp = new_dp

        # Sum probabilities of being at battery room with any battery
        total_prob = sum(p for (x,y,bat), p in dp.items() if (x,y) == battery_room)
        results.append(f"{total_prob:.8f}")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()

import sys
from fractions import Fraction

def solve():
    # Assuming 4x4 grid
    N = 4

    def get_neighbors(pos, junk):
        r, c = pos // N, pos % N
        neighbors = []
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N:
                p = nr * N + nc
                if p != junk:
                    neighbors.append(p)
        return neighbors

    for line in sys.stdin:
        parts = line.split()
        if not parts:
            continue
        battery = int(parts[0])
        if battery == 0:
            break
        start = int(parts[1]) - 1
        battery_room = int(parts[2]) - 1
        junk_room = int(parts[3]) - 1

        # dp[pos] = probability of being at pos with current battery
        dp = [Fraction(0)] * (N*N)
        dp[start] = Fraction(1)

        for _ in range(battery):
            new_dp = [Fraction(0)] * (N*N)
            for pos in range(N*N):
                if dp[pos] == 0:
                    continue
                if pos == junk_room:
                    continue
                neighbors = get_neighbors(pos, junk_room)
                if not neighbors:
                    # stuck, stays? or lost?
                    new_dp[pos] += dp[pos]
                else:
                    prob = Fraction(1, len(neighbors))
                    for nb in neighbors:
                        new_dp[nb] += dp[pos] * prob
            dp = new_dp

        result = dp[battery_room]
        # Print as fraction or decimal
        print(f"{float(result):.6f}")

